_CORE_SRC = '# Action format: [(from_node, to_node, unit_type, count), ...]\n# Payout: "if capacity_0 == capacity_1": each serves min(capacity_0, d / 2).\n# Otherwise the bigger side serves min(capacity_big, d), and the smaller side\n# serves min(capacity_small, d - served_big).\n# Cost: "upkeep_p = 3.0 * (10 - heavy_p at own base)\n#                    + 1.0 * (20 - light_p at own base)".\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 70\nTYPES = ("heavy", "light")\nCAPACITY = (8, 3)\nUPKEEP = (3.0, 1.0)\n\n\ndef payout(own, opponent, demand):\n    """Return both revenues, following the priority rule exactly."""\n    if own == opponent:\n        served = min(own, demand / 2.0)\n        return served, served\n    if own > opponent:\n        ours = min(own, demand)\n        return ours, min(opponent, demand - ours)\n    theirs = min(opponent, demand)\n    return min(own, demand - theirs), theirs\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for row in adjacency:\n        row.sort()\n    distances = []\n    for source in range(n):\n        row = [n + 1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] == n + 1:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n    hops = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source != target:\n                for v in adjacency[source]:\n                    if distances[v][target] == distances[source][target] - 1:\n                        hops[source][target] = v\n                        break\n    return adjacency, distances, hops\n\n\ndef legal_action(have, want, adjacency, distances, hops):\n    """Closest-first matching; availability always comes from start-of-turn units."""\n    combined = {}\n    n = len(adjacency)\n    for kind in range(2):\n        surplus = [max(0, have[kind][v] - want[kind][v]) for v in range(n)]\n        deficit = [max(0, want[kind][v] - have[kind][v]) for v in range(n)]\n        pairs = sorted(\n            (distances[s][t], s, t)\n            for s in range(n) if surplus[s]\n            for t in range(n) if deficit[t] and s != t\n        )\n        for _, s, t in pairs:\n            count = min(surplus[s], deficit[t])\n            hop = hops[s][t]\n            if count and hop >= 0:\n                surplus[s] -= count\n                deficit[t] -= count\n                key = (s, hop, kind)\n                combined[key] = combined.get(key, 0) + count\n\n    available = [row[:] for row in have]\n    result = []\n    for (source, target, kind), count in sorted(combined.items()):\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if target not in adjacency[source]:\n            continue\n        count = min(int(count), available[kind][source])\n        if count <= 0:\n            continue\n        available[kind][source] -= count\n        result.append((int(source), int(target), TYPES[kind], int(count)))\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.base_estimates = {}\n        self.sightings = {}\n        self.previous_plan = None\n        self.bad_reports = 0\n        self.conservative = False\n\n    def _forecast(self, obs, horizon):\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        home = obs["player_base"]\n        enemy_home = obs["opponent_base"]\n        demand = obs.get("demand", [None] * n)\n        counters = obs.get("surge_turns_left", [None] * n)\n        forecast = []\n        for v in range(n):\n            if v == home or v == enemy_home:\n                self.base_estimates[v] = 0.0\n                forecast.append([(0.0, 0.0)] * horizon)\n                continue\n            if demand[v] is not None:\n                counter = int(counters[v] or 0)\n                base = float(demand[v]) / (3.0 if counter else 1.0)\n                self.base_estimates[v] = round(base, 1)\n                self.sightings[v] = (turn, counter)\n            base = self.base_estimates.get(v, 3.8)\n            seen_turn, counter = self.sightings.get(v, (turn - 10, 0))\n            row = []\n            for offset in range(horizon):\n                elapsed = max(0, turn + offset - seen_turn)\n                probability = (\n                    1.0 if elapsed < counter\n                    else 1.0 - 0.9 ** min(elapsed, 3)\n                )\n                row.append((base, probability))\n            forecast.append(row)\n        return forecast\n\n    def _plan(self, obs, have, forecast, deadline):\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        _, distances, _ = self.map_data\n        horizon = len(forecast[0])\n        opponent = [\n            8 * obs["opponent_heavy"][v] + 3 * obs["opponent_light"][v]\n            for v in range(n)\n        ]\n        available = [row[:] for row in have]\n        want = [[0] * n for _ in range(2)]\n        assigned_capacity = [0] * n\n        cache = {}\n\n        def tail_value(node, capacity, arrival):\n            key = (node, capacity, arrival)\n            value = cache.get(key)\n            if value is not None:\n                return value\n            total = 0.0\n            enemy = opponent[node]\n            for offset in range(arrival, horizon):\n                base, probability = forecast[node][offset]\n                a, b = payout(capacity, enemy, base)\n                c, d = payout(capacity, enemy, round(3.0 * base, 1))\n                total += (a - b) * (1.0 - probability) + (c - d) * probability\n            cache[key] = total\n            return total\n\n        # The priority rule is NOT concave at capacity ties. Evaluate bundles as\n        # well as single-unit marginals so that crossing a tie is considered.\n        for iteration in range(60):\n            if time.perf_counter() >= deadline:\n                break\n            best = None\n            best_rate = 0.08\n            for kind in range(2):\n                sources = [s for s in range(n) if available[kind][s]]\n                if not sources:\n                    continue\n                for node in range(n):\n                    if node == home or node == obs["opponent_base"]:\n                        continue\n                    source = min(sources, key=lambda s: (distances[s][node], s))\n                    travel = distances[source][node]\n                    arrival = max(0, travel - 1)\n                    if arrival >= horizon:\n                        continue\n                    old_capacity = assigned_capacity[node]\n                    old_value = tail_value(node, old_capacity, arrival)\n                    limit = available[kind][source]\n                    for count in range(1, limit + 1):\n                        capacity = old_capacity + CAPACITY[kind] * count\n                        gain = tail_value(node, capacity, arrival) - old_value\n                        # Costs include every travelling turn, even before arrival.\n                        gain -= UPKEEP[kind] * count * horizon\n                        # Staying and retaining a prior target need a clear\n                        # improvement before being displaced by another plan.\n                        if source == node:\n                            gain += 0.20 * horizon * count\n                        if self.previous_plan is not None:\n                            retained = min(\n                                count,\n                                max(0, self.previous_plan[kind][node] - want[kind][node]),\n                            )\n                            gain += 0.08 * horizon * retained\n                        rate = gain / count\n                        if rate > best_rate + 1e-9:\n                            best_rate = rate\n                            best = (kind, source, node, count)\n                if time.perf_counter() >= deadline:\n                    break\n            if best is None:\n                break\n            kind, source, node, count = best\n            available[kind][source] -= count\n            want[kind][node] += count\n            assigned_capacity[node] += CAPACITY[kind] * count\n\n        # Unprofitable units head home; units do not disappear from the plan.\n        for kind in range(2):\n            want[kind][home] += sum(available[kind])\n        return want\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs["edges"])\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n            if self.bad_reports >= 2:\n                self.conservative = True\n        have = [list(obs["player_heavy"]), list(obs["player_light"])]\n        horizon = max(1, min(12, N_TURNS - int(obs["turn"])))\n        forecast = self._forecast(obs, horizon)\n        want = self._plan(obs, have, forecast, deadline)\n        adjacency, distances, hops = self.map_data\n        action = legal_action(have, want, adjacency, distances, hops)\n        self.previous_plan = want\n        if self.conservative:\n            # One explicitly validated move per source and type is the simplest\n            # possible emission mode after repeated external error feedback.\n            seen = set()\n            simple = []\n            for move in action:\n                key = (move[0], move[2])\n                if key not in seen:\n                    seen.add(key)\n                    simple.append(move)\n            return simple\n        return action\n'
