_FALLBACK_SRC = '# Exact action format: [(from_node, to_node, unit_type, count), ...]\n# Payout: equal capacities each serve min(capacity, demand / 2); otherwise\n# the larger capacity serves min(capacity, demand) first, and the smaller\n# serves min(capacity, demand - served_big).\n# Upkeep: each heavy away from its own base costs 3.0 per turn; each light\n# away from its own base costs 1.0. Units at their own base cost nothing.\n# This conservative fallback uses lights only. Heavy units, if already\n# deployed in an observation, are recalled. No demand history is retained.\n\nfrom collections import deque\nimport time\n\nTIME_BUDGET = 0.25\nN_TURNS = 70\n\n\ndef payout(own_capacity, opponent_capacity, demand):\n    """Return both revenues, exactly following the priority-capacity rule."""\n    if own_capacity == opponent_capacity:\n        share = min(own_capacity, demand / 2.0)\n        return share, share\n    if own_capacity > opponent_capacity:\n        own = min(own_capacity, demand)\n        return own, min(opponent_capacity, demand - own)\n    opponent = min(opponent_capacity, demand)\n    return min(own_capacity, demand - opponent), opponent\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for neighbours in adjacency:\n        neighbours.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source != target and distances[source][target] > 0:\n                next_hop[source][target] = next(\n                    v for v in adjacency[source]\n                    if distances[v][target] == distances[source][target] - 1\n                )\n    return adjacency, distances, next_hop\n\n\ndef conservative_plan(obs, distances, deadline):\n    """Choose a small, sustainable allocation; surplus always belongs at home."""\n    n = obs["n_nodes"]\n    home = obs["player_base"]\n    enemy_home = obs["opponent_base"]\n    remaining = max(0, N_TURNS - obs["turn"])\n    light = obs["player_light"]\n    total = sum(light)\n    desired = [0] * n\n    desired[home] = total\n\n    baseline = [0.0] * n\n    available = []\n    for v in range(n):\n        if v == home or v == enemy_home:\n            continue\n        demand = obs["demand"][v]\n        surge = obs["surge_turns_left"][v]\n        if demand is None or surge is None:\n            continue\n        # Never deliberately enter a fight, including a small-capacity fight.\n        opponent = (\n            8 * obs["opponent_heavy"][v] + 3 * obs["opponent_light"][v]\n        )\n        if opponent:\n            continue\n        baseline[v] = float(demand) / (3.0 if surge > 0 else 1.0)\n        available.append(v)\n\n    # Select whole-unit increments, nearest first. Require a comfortable\n    # sustainable profit, enough time to repay travel in both directions,\n    # and no speculative credit for future surges.\n    candidates = []\n    for v in available:\n        distance = distances[home][v]\n        if distance <= 0:\n            continue\n        for k in range(1, total + 1):\n            before, _ = payout(3 * (k - 1), 0, baseline[v])\n            after, _ = payout(3 * k, 0, baseline[v])\n            net = after - before - 1.0\n            if net <= 0.35:\n                break\n            earning_turns = max(0, remaining - distance + 1)\n            travel_allowance = 2.0 * max(0, distance - 1)\n            if net * earning_turns <= travel_allowance + 1.0:\n                break\n            candidates.append((distance, -net, v, k))\n\n    candidates.sort()\n    for _, _, v, k in candidates:\n        if time.perf_counter() >= deadline:\n            break\n        if desired[home] <= 0:\n            break\n        if desired[v] == k - 1:\n            desired[v] += 1\n            desired[home] -= 1\n\n    # A temporary surge next to home is safe to harvest: moving there earns\n    # immediately, and returning home next turn has zero upkeep. Only use\n    # currently unassigned home units; never draw units away from other jobs.\n    spare_home = min(light[home], desired[home])\n    for v in sorted(available, key=lambda x: (-float(obs["demand"][x]), x)):\n        if distances[home][v] != 1:\n            continue\n        if time.perf_counter() >= deadline:\n            break\n        while spare_home > 0:\n            k = desired[v]\n            before, _ = payout(3 * k, 0, float(obs["demand"][v]))\n            after, _ = payout(3 * (k + 1), 0, float(obs["demand"][v]))\n            if after - before <= 1.5:\n                break\n            desired[v] += 1\n            desired[home] -= 1\n            spare_home -= 1\n\n    return desired\n\n\ndef legal_action(obs, desired, adjacency, distances, next_hop):\n    """Match surpluses to deficits, then validate against start-turn inventory."""\n    n = obs["n_nodes"]\n    home = obs["player_base"]\n    proposals = {}\n\n    def propose(source, target, kind, count):\n        if source == target or count <= 0:\n            return\n        hop = next_hop[source][target]\n        if hop >= 0:\n            key = (source, hop, kind)\n            proposals[key] = proposals.get(key, 0) + count\n\n    for source, count in enumerate(obs["player_heavy"]):\n        propose(source, home, "heavy", count)\n\n    have = obs["player_light"]\n    surplus = [max(0, have[v] - desired[v]) for v in range(n)]\n    deficit = [max(0, desired[v] - have[v]) for v in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t]\n        if distances[s][t] > 0\n    )\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count:\n            surplus[source] -= count\n            deficit[target] -= count\n            propose(source, target, "light", count)\n\n    inventory = {\n        "heavy": list(obs["player_heavy"]),\n        "light": list(obs["player_light"]),\n    }\n    result = []\n    for (source, target, kind), count in sorted(proposals.items()):\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if target not in adjacency[source]:\n            continue\n        count = min(int(count), int(inventory[kind][source]))\n        if count <= 0:\n            continue\n        inventory[kind][source] -= count\n        result.append((int(source), int(target), kind, int(count)))\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        key = (n, tuple(tuple(edge) for edge in obs["edges"]))\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, obs["edges"])\n            self.map_key = key\n        adjacency, distances, next_hop = self.map_data\n        desired = conservative_plan(obs, distances, deadline)\n        return legal_action(obs, desired, adjacency, distances, next_hop)\n'
